import React from 'react';
const videoFile = process.env.PUBLIC_URL + '/video/Raaayhan  - Naruto and Sasuke Vs Jigen Fight 4K 60Fps [Eng sub].webm';

function Sasuke({ hokhage }) {

  if (!hokhage || hokhage.length === 0) {
    return <p>No data available</p>;
  }
  return (
    <div>
      {hokhage.map((value) => (

        <div key={value.id} className="mat">
          <video
            width="560"
            height="315"
            controls
            autoPlay
            muted
            preload="auto"
            src={videoFile}
            title={value.name}
          >
            Your browser does not support the video tag.
          </video>

          <br /><br />
          <h2>{value.name}</h2>
          <h3>Type: {value.type}</h3>
          <p>{value.description}</p>
          <h4>Rating: {value.rating}</h4>
        </div>
      ))}
    </div>
  );
}
export default Sasuke;
